args.sql:
SELECT AVG(UPDR) AS mean_UPDR
FROM (
    SELECT JSONB_EXTRACT_PATH_TEXT(risk_indicators, 'UPDR')::NUMERIC AS UPDR
    FROM transactionrecord
    WHERE JSONB_EXTRACT_PATH_TEXT(risk_indicators, 'UPDR') IS NOT NULL
) AS subquery;

